// A role is a stance the assistant takes for one conversation: a document that
// is injected as a system message, plus — optionally — the specification for the
// formal analysis written after that conversation goes quiet.
//
// Roles are DATA. Adding one is an entry in `ROLES`, not a code change anywhere
// else: the pill lists the catalog, `buildSystemMessages` injects whatever
// `document` says, and any role carrying a `sessionAnalysis` spec gets a note
// generated by the same generator the Therapist uses.
import { isTimelineHeadingLine, timelinePromptSection } from './timeline'
import type { RoleSessionRisk } from './types'

export type RoleId = 'therapist'

/** One heading in the stored session note, in the order the note lays them out. */
export interface RoleSessionSection {
  key: string
  heading: string
  /** What the model is told to put under this heading. */
  instruction: string
}

export interface RoleSessionAnalysisSpec {
  /**
   * The default project the note is filed under when the conversation itself is
   * not filed anywhere. Matched by name against the built-in sources.
   */
  projectName: string
  /** Slug used in the written file name. */
  fileSlug: string
  /** `document_type` in the file's frontmatter, so the indexer can recognize it. */
  documentType: string
  /** A conversation shorter than this is not a session and gets no note. */
  minTurns: number
  /** Cap on entries the note's TIMELINE block may emit. */
  maxTimelineEntries: number
  sections: RoleSessionSection[]
  /** Prepended to the note file and shown above the note in the UI. */
  disclaimer: string
  /** The system prompt that produces the note. */
  systemPrompt: string
}

export interface RoleDefinition {
  id: RoleId
  name: string
  /** One-line specialty, shown as the hint in the Role pill. */
  specialty: string
  /** FontAwesome name resolved through `projectIconRegistry`. */
  icon: string
  color: string
  /** Shown under the role in the pill panel, and on the session note. */
  description: string
  /** The role document: injected verbatim as a system message. */
  document: string
  sessionAnalysis?: RoleSessionAnalysisSpec
}

/**
 * Bump when a role document or a session-analysis prompt changes materially.
 * Session notes are hash-gated on it, so a revision regenerates them.
 */
export const ROLE_PROMPT_VERSION = 'v1-therapist'

