export const ROLES: readonly RoleDefinition[] = [THERAPIST]

const ROLE_BY_ID: ReadonlyMap<string, RoleDefinition> = new Map(ROLES.map((role) => [role.id, role]))

export function isRoleId(value: unknown): value is RoleId {
  return typeof value === 'string' && ROLE_BY_ID.has(value)
}

export function getRole(roleId: string | null | undefined): RoleDefinition | null {
  if (!roleId) return null
  return ROLE_BY_ID.get(roleId) ?? null
}

/** Roles whose conversations produce a stored analysis. */
export function rolesWithSessionAnalysis(): RoleDefinition[] {
  return ROLES.filter((role) => Boolean(role.sessionAnalysis))
}

/**
 * The system message a role contributes to a conversation. Kept here rather than
 * in `ipc.ts` so the framing around the document travels with the catalog.
 */
export function roleSystemMessage(role: RoleDefinition): string {
  return `${role.document}

This role governs your manner and priorities for this conversation. It does not override your safety obligations, and it does not license you to claim credentials you do not have. The user selected it and can change it at any time.`
}

// ---------------------------------------------------------------------------
// Session note parsing and rendering
// ---------------------------------------------------------------------------

export interface ParsedSessionSection {
  key: string
  heading: string
  body: string
}

export interface ParsedSessionNote {
  title: string
  summary: string
  risk: RoleSessionRisk
  sections: ParsedSessionSection[]
}

const RISK_VALUES: RoleSessionRisk[] = ['none', 'monitor', 'urgent']

export function normalizeSessionRisk(value: unknown): RoleSessionRisk {
  if (typeof value !== 'string') return 'none'
  const lowered = value.trim().toLowerCase()
  for (const risk of RISK_VALUES) {
    if (lowered === risk || lowered.startsWith(`${risk} `) || lowered.startsWith(`${risk}:`)) return risk
  }
  // An unrecognized value is treated as worth a look rather than as nothing: a
  // model that wrote something other than the three words was trying to say
  // something, and silently downgrading it to "none" is the one failure mode
  // this field must not have.
  return lowered ? 'monitor' : 'none'
}

function slugifyHeading(heading: string): string {
  return heading
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 48)
}

const TITLE_FALLBACK = 'Session note'
const MAX_TITLE_CHARS = 120
const MAX_SUMMARY_CHARS = 1_200

function cleanLine(value: string): string {
  return value.replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim()
}

/**
 * Reads the model's session note back into structure. Tolerant on purpose: a
 * note that lost its TITLE line is still a note, and dropping the whole record
 * because a heading was worded differently would lose the session entirely.
 *
 * `sections` fixes the expected order and canonical keys; anything the model
 * added beyond them is kept, appended, rather than discarded.
 */
export function parseSessionNote(raw: string, sections: RoleSessionSection[]): ParsedSessionNote | null {
  const text = raw
    .replace(/^\s*```(?:markdown|text)?\s*/i, '')
    .replace(/\s*```\s*$/, '')
    .replace(/\r\n/g, '\n')
    .trim()
  if (!text) return null

  const headingByKey = new Map(sections.map((section) => [section.key, section]))
  const keyByNormalizedHeading = new Map(sections.map((section) => [slugifyHeading(section.heading), section.key]))

  let title = ''
  let summary = ''
  let risk: RoleSessionRisk = 'none'
  const collected = new Map<string, { heading: string; lines: string[] }>()

  let currentKey: string | null = null
  let inSummary = false
  // The TIMELINE block is parsed separately (`parseTimelineBlock`) and stored
  // with the note whole. Skipping it here rather than truncating at it means a
  // model that put the block mid-document does not cost us everything after it.
  let inTimeline = false

  for (const line of text.split('\n')) {
    if (isTimelineHeadingLine(line)) {
      inTimeline = true
      inSummary = false
      currentKey = null
      continue
    }

    const headingMatch = line.match(/^\s{0,3}#{1,4}\s+(.+?)\s*$/)
    if (inTimeline) {
      // Only a real heading ends the block — its own rows start with "- ".
      if (!headingMatch) continue
      inTimeline = false
    }
    if (headingMatch) {
      inSummary = false
      const heading = cleanLine(headingMatch[1]).replace(/^[0-9]+[.)]\s*/, '')
      const normalized = slugifyHeading(heading)
      const key = keyByNormalizedHeading.get(normalized) ?? normalized
      if (!key) continue
      currentKey = key
      if (!collected.has(key)) {
        collected.set(key, { heading: headingByKey.get(key)?.heading ?? heading, lines: [] })
      }
      continue
    }

    if (currentKey === null) {
      const titleMatch = line.match(/^\s*\**title\**\s*:\s*(.*)$/i)
      if (titleMatch) {
        title = cleanLine(titleMatch[1].replace(/\*/g, '')).slice(0, MAX_TITLE_CHARS)
        inSummary = false
        continue
      }
      const riskMatch = line.match(/^\s*\**risk\**\s*:\s*(.*)$/i)
      if (riskMatch) {
        risk = normalizeSessionRisk(cleanLine(riskMatch[1].replace(/\*/g, '')))
        inSummary = false
        continue
      }
      const summaryMatch = line.match(/^\s*\**summary\**\s*:\s*(.*)$/i)
      if (summaryMatch) {
        summary = cleanLine(summaryMatch[1].replace(/\*/g, ''))
        inSummary = true
        continue
      }
      // A summary that wrapped onto following lines keeps accumulating until a
      // blank line or the next labelled field.
      if (inSummary) {
        const continuation = cleanLine(line)
        if (!continuation) {
          inSummary = false
          continue
        }
        summary = summary ? `${summary} ${continuation}` : continuation
        continue
      }
      continue
    }

    collected.get(currentKey)?.lines.push(line)
  }

  const ordered: ParsedSessionSection[] = []
  for (const section of sections) {
    const found = collected.get(section.key)
    const body = (found?.lines.join('\n') ?? '').trim()
    if (!body) continue
    ordered.push({ key: section.key, heading: section.heading, body })
  }
  for (const [key, value] of collected) {
    if (headingByKey.has(key)) continue
    const body = value.lines.join('\n').trim()
    if (!body) continue
    ordered.push({ key, heading: value.heading, body })
  }

  if (ordered.length === 0 && !summary) return null

  const derivedSummary = summary || ordered[0]?.body.split('\n').find((line) => line.trim())?.trim() || ''

  return {
    title: title || TITLE_FALLBACK,
    summary: derivedSummary.slice(0, MAX_SUMMARY_CHARS),
    risk,
    sections: ordered,
  }
}

export const SESSION_RISK_LABELS: Record<RoleSessionRisk, string> = {
  none: 'No risk content',
  monitor: 'Monitor',
  urgent: 'Urgent',
}

/**
 * The note as it is written to disk. Frontmatter first so the document indexer
 * and any later reader can tell what this file is without parsing the prose.
 */
export function renderSessionNoteMarkdown(input: {
  role: RoleDefinition
  note: ParsedSessionNote
  conversationTitle: string
  conversationId: string
  sessionDate: string
  generatedAt: string
  model: string | null
  turns: number
  assistantName: string
  timelineBlock: string
}): string {
  const spec = input.role.sessionAnalysis
  const lines: string[] = [
    '---',
    `document_type: ${spec?.documentType ?? 'holmes_session_note'}`,
    `role: ${input.role.id}`,
    `conversation_id: ${input.conversationId}`,
    `session_date: ${input.sessionDate}`,
    `generated_at: ${input.generatedAt}`,
    `risk: ${input.note.risk}`,
    `turns: ${input.turns}`,
    `model: ${input.model ?? 'unknown'}`,
    '---',
    '',
    `# ${input.note.title}`,
    '',
    `Session: ${input.sessionDate} · ${input.turns} turns · Role: ${input.role.name}`,
    '',
    `> ${spec?.disclaimer ?? THERAPIST_DISCLAIMER}`,
    '',
  ]

  if (input.note.risk !== 'none') {
    lines.push(
      `> **Risk screen: ${SESSION_RISK_LABELS[input.note.risk]}.** See the Risk and Safety Screen section below.`,
      ''
    )
  }

  lines.push('## Summary', '', input.note.summary || 'No summary was produced.', '')

  for (const section of input.note.sections) {
    if (section.key === 'summary') continue
    lines.push(`## ${section.heading}`, '', section.body, '')
  }

  if (input.timelineBlock.trim()) {
    lines.push(input.timelineBlock.trim(), '')
  }

  lines.push(
    '---',
    '',
    `Source conversation: "${input.conversationTitle}" (${input.conversationId})`,
    '',
    `_Generated locally by ${input.assistantName}. Not a clinical record._`,
    ''
  )

  return lines.join('\n')
}
